(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7645],{20063:(e,t,a)=>{"use strict";var i=a(47260);a.o(i,"useParams")&&a.d(t,{useParams:function(){return i.useParams}}),a.o(i,"usePathname")&&a.d(t,{usePathname:function(){return i.usePathname}}),a.o(i,"useRouter")&&a.d(t,{useRouter:function(){return i.useRouter}}),a.o(i,"useSearchParams")&&a.d(t,{useSearchParams:function(){return i.useSearchParams}})},56181:(e,t,a)=>{"use strict";a.d(t,{A:()=>s});var i=a(95155),o=a(20063),r=a(52619),n=a.n(r);function s(e){let{title:t,basePath:a,data:r}=e,s=(0,o.useRouter)();return(0,i.jsxs)("div",{className:"min-h-screen flex flex-col bg-white dark:bg-zinc-900 dark:text-zinc-100",children:[(0,i.jsx)("header",{className:"sticky z-10 bg-white/90 dark:bg-zinc-900/90 backdrop-blur border-b border-slate-200 dark:border-zinc-700",style:{top:"calc(4rem + env(safe-area-inset-top, 0px))"},children:(0,i.jsxs)("div",{className:"max-w-3xl mx-auto px-4 py-3 flex items-center justify-between gap-3",children:[(0,i.jsx)("button",{onClick:()=>s.back(),className:"px-3 py-1 rounded border text-sm bg-white hover:bg-slate-50 dark:bg-zinc-900 dark:text-zinc-100 dark:border-zinc-700",children:"Close"}),(0,i.jsx)("h1",{className:"text-sm font-semibold tracking-widest opacity-80",children:t}),(0,i.jsx)("div",{className:"w-[64px]","aria-hidden":!0})]})}),(0,i.jsx)("main",{className:"flex-1",children:(0,i.jsxs)("div",{className:"max-w-3xl mx-auto p-4 space-y-3",children:[0===r.length&&(0,i.jsx)("p",{className:"text-sm text-slate-500 dark:text-zinc-400 px-1 py-6 text-center",children:"No system notes for this variant yet."}),r.map(e=>(0,i.jsx)(n(),{href:"".concat(a,"/").concat(e.slug),prefetch:!1,className:"group block rounded-xl border border-slate-200 bg-white px-4 py-3 transition hover:bg-slate-50 dark:border-zinc-700 dark:bg-zinc-900 dark:hover:bg-zinc-800",children:(0,i.jsxs)("div",{className:"flex items-start justify-between gap-4",children:[(0,i.jsxs)("div",{className:"min-w-0",children:[(0,i.jsx)("div",{className:"font-semibold text-slate-900 dark:text-zinc-100",children:e.title}),e.subtitle&&(0,i.jsx)("div",{className:"mt-0.5 text-sm text-slate-600 dark:text-zinc-300",children:e.subtitle})]}),(0,i.jsx)("div",{className:"shrink-0 text-slate-400 text-xl transition-transform group-hover:translate-x-0.5 dark:text-zinc-500",children:"›"})]})},e.slug))]})})]})}},89473:(e,t,a)=>{"use strict";a.r(t),a.d(t,{default:()=>n});var i=a(95155),o=a(56181);let r=[{slug:"tcas",title:"TCAS: Traffic Alert and Collision Avoidance System",subtitle:"Traffic-Advisory-only — no Resolution Advisories on the S-92. The sensitivity levels, symbol set, and pop-up display logic behind every TA.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 6 (Navigation — TCAS: Introduction, TCAS Operation, Display Characteristics and Modes, Controls and Functions, Initial Built-in Test).",sections:[{heading:"What it does — and what it doesn't",paragraphs:["TCAS on the S-92 issues Traffic Advisories (TAs) only — there is no Resolution Advisory capability. It detects and tracks nearby transponder-equipped aircraft (ATCRBS Mode A/C or Mode S), computing range, relative bearing, closure rate, and — if the intruder reports it — relative altitude and vertical trend, to predict time to and separation at Closest Point of Approach (CPA). A TA fires when time to CPA is 15 to 30 seconds, alerting the crew with a 'Traffic, Traffic' aural and a TRAFFIC annunciation on the ADI.","TCAS traffic can be displayed together with weather radar, EGPWS, and/or lightning sensor data. ATC procedures and see-and-avoid remain the primary means of separation — TCAS is a backup, particularly valuable if communication with ATC is lost."]},{heading:"Range, altitude bands, and sensitivity levels",paragraphs:["Nominal maximum range is 18 NM, though intruders can occasionally be seen out to 36 NM — TCAS reduces its tracking volume in high-density areas to limit interference and processing load. It tracks up to 45 aircraft and displays up to 30.","Two sensitivity levels adjust the TA threshold by altitude band, to avoid nuisance alerts in busy low-level traffic: SL A applies below 2,000 ft AGL or with the landing gear extended; SL B applies in all other flight conditions."],table:{columns:["Level","TA triggers"],rows:[["SL A","Altitude separation closing to <600 ft within 20 s at current rate; OR separation <600 ft altitude AND <0.20 NM range; OR a non-altitude-reporting intruder within 15 s or 0.20 NM"],["SL B","Altitude separation closing to <800 ft within 30 s at current rate; OR separation <800 ft altitude AND <0.55 NM range; OR a non-altitude-reporting intruder within 20 s or 0.55 NM"]]}},{heading:"Display modes and symbols",paragraphs:["Three display volumes select how much airspace is shown: Normal (−2,700 to +2,700 ft), Above (−2,700 to +9,000 ft), Below (−9,000 to +2,700 ft)."],table:{columns:["Symbol","Meaning"],rows:[["Open diamond","Intruder beyond 1,200 ft relative altitude or 5 NM range — not yet a threat"],["Filled diamond","Intruder within 1,200 ft and 5 NM — proximate traffic, still not considered a threat"],["Filled yellow circle","Traffic Advisory — the intruder is potentially hazardous"]]},note:"An altitude tag in hundreds of feet shows above (+) or below (−) the symbol, with a trend arrow if vertical rate exceeds 500 fpm. If TCAS can't resolve an intruder's bearing, it shows a no-bearing text advisory instead — format TA n.nNM \xb1aa with a climb/descend arrow — positioned below the aircraft symbol; up to two no-bearing intruders can be shown at once, ranked by priority."},{heading:"Pop-up display",paragraphs:["If no TCAS display is currently selected and more than three MFDs are operational, a traffic warning forces a NAV ARC page with TCAS onto an available display automatically — center MFD first (if installed), then pilot's inboard MFD, then copilot's inboard MFD. EGPWS pop-up takes precedence over TCAS if both trigger together. Pop-up is disabled when only two or fewer MFDs are functional."]},{heading:"Controls and self-test",paragraphs:["TCAS is controlled from the PFD ARC and NAV displays: press OVLY then TCAS to bring up the display, CTL to activate TCAS controls, and BAND repeatedly to step through ABV/NORM/BLW. STBY places TCAS in standby — reactivate by pressing OVLY and reselecting TCAS.","Initial Built-In Test (IBIT) runs on the ground via the maintenance data computer: press HEALTH, line down to AVIONICS, SUB STAT, line down to TCAS, then IBIT."]}]},{slug:"weather-radar",title:"Primus 700A Weather Radar",subtitle:"STC/REACT gain handling, the two ground-mapping modes, and the microwave-radiation clearance you need before running it on the ground.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 6 (Navigation — Primus 700A Weather Radar: Introduction, Components, Weather Radar Control Panel, Modes of Operation, Secondary Operating Modes, Variable Controls, Normal Operation).",sections:[{heading:"What it is",paragraphs:["The Honeywell Primus 700A is an X-band digital radar providing weather detection and high-resolution ground mapping, detecting storms within 60\xb0 of the flight path and displaying them on the MFDs. Hardware: a transmitter/receiver, antenna pedestal, and control panel, all in the forward avionics compartment/cockpit lower console.","The radar interfaces with the weight-on-wheels switch (for forced standby), ADC1 (altitude/airspeed, for autotilt and turbulence detection), and AHRS1 (pitch/roll/heading/rates, for stabilization and turbulence detection). If either ADC1 or AHRS1 fails, autotilt, stabilization, and turbulence detection are lost — but basic weather detection continues unaffected."]},{heading:"Primary modes",table:{columns:["Mode","What it does"],rows:[["STBY","Standby — antenna centered, transmitter disabled, display memory erased"],["FSBY (Forced Standby)","Automatic, non-selectable — WOW-triggered, inhibits both transmitter and antenna scan to eliminate X-band radiation hazard on the ground"],["WX","Weather detection: >2 in/hr magenta, 0.47–2 in/hr red, 0.16–0.47 in/hr yellow, 0.04–0.16 in/hr green (preset gain)"],["WX/RCT","Weather with REACT (Rain Echo Attenuation Compensation) — a blue field marks areas where further compensation isn't possible and storms may go undetected; targets there appear magenta and should be considered very dangerous. Variable gain is unavailable in this mode"],["1 GMAP","Ground mapping, maximum sensitivity/resolution for small targets — cyan/yellow/magenta by return strength, with a red 'dead zone' for targets inside minimum range"],["2 GMAP","Ground mapping, best configuration for terrain mapping — same cyan/yellow/magenta coding"],["TST","Self-test pattern for system verification; color-display faults should be reported to maintenance"]]},note:"Weather targets are not calibrated while in either ground-mapping mode."},{heading:"Secondary modes",table:{columns:["Function","Detail"],rows:[["Turbulence detection (TRB)","Available in WX or WX/RCT — shows turbulence within 50 NM as white areas (WX/T or R/T in the mode field). Only turbulence within rainfall is detectable, not clear-air turbulence"],["Target Alert (TGT)","5–200 NM selectable range, monitors 50 NM beyond the selected range and \xb17.5\xb0 of heading for red/magenta returns; alerts by changing from green 'armed' T to amber TGT. Inactive within the selected range itself; no variable gain in this mode"],["Sector (SECT)","Toggles between 120\xb0 full azimuth and 60\xb0 sector scan"],["Stabilization","Automatic antenna stabilization from pitch/roll data; disable by pressing *CR and TGT together (shows STAB annunciation when off)"],["Roll Offset Compensation (ROC)","Adds up to 2\xb0 left/right roll offset to correct for antenna mounting or roll-trim errors — must be adjusted in level flight over level ground, entered/exited by pressing TRB and SECT together"],["Clutter Reduction (*CR)","In WX mode: Ground Clutter Reduction (GCR), reduces ground clutter but also weather targets, times out after 20 s. In 1 GMAP: CR1 (high sea states) then CR2 (moderate sea states) on successive presses. Available only at 50 NM range or less"]]}},{heading:"Gain and tilt",paragraphs:["Gain is normally automatic — Sensitivity Time Control (STC) compensates for signal weakening with distance, and REACT (when active) further adjusts sensitivity to compensate for attenuation through weather. GAIN can be pulled out for manual control: clockwise from MIN increases gain to maximum at the 12 o'clock position, then continuing clockwise progressively reduces STC compensation toward MAX.","TILT selects manual or automatic (autotilt) antenna tilt. In manual mode (TILT pushed in), tilt varies \xb115\xb0 with the first \xb15\xb0 expanded for precision; stabilization, if enabled, still functions in manual tilt. In autotilt (TILT pulled out), the antenna automatically sets the optimum tilt for altitude and range, trimmable \xb12\xb0 — but autotilt cannot compensate for high ground, and at long ranges (200–300 NM) earth curvature will put ground targets in the center of the display regardless."]},{heading:"The hard warning",paragraphs:["The radar generates microwave radiation. Before ground operation, the area within the 270\xb0 forward sector of the nose, out to a minimum of 100 ft, must be clear of personnel, reflecting surfaces, flammable materials, and large metallic objects (hangars, other aircraft). Avoid radar operation within 100 ft of refueling."]}]},{slug:"egpws",title:"EGPWS",subtitle:"Five active modes — Mode 1 isn't used on the S-92 — plus Look-Ahead, Peaks Mode terrain coloring, and the geometric altitude behind all of it.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 4 (Avionics Management System — Enhanced Ground Proximity Warning System: Introduction, Theory of Operation, Terrain Display, Auto Range and Cell Expansion, Pop Up Mode, Look Ahead Mode, Basic Modes, Controls, EGPWS Test). The S-92 uses EGPWS as its aircraft aural warning generator.",sections:[{heading:"What it is",paragraphs:["EGPWS reduces Controlled Flight Into Terrain (CFIT) risk through two complementary alert families: the basic modes (2 through 6), based on radar altitude, which prevent descent into level or evenly sloping terrain; and the Look-Ahead modes, based on GPS position compared against terrain and obstacle databases, which catch sharply rising terrain or man-made obstacles ahead of the flight path.","Note that Mode 1 (excessive descent rate) is not used on the S-92 — active protection starts at Mode 2.","A geometric altitude — barometric altitude, radar altitude, and GPS altitude combined — drives the terrain display and alerting, preventing errors from a wrong altimeter setting, a faulty altimeter, or extreme cold. The obstacle database covers man-made structures over 100 ft high; not all obstacles are covered worldwide, and power lines are generally not included."]},{heading:"Terrain display colors",table:{columns:["Color","Meaning"],rows:[["Red","Terrain or obstacles well above the aircraft"],["Yellow","Terrain or obstacles close to aircraft elevation"],["Green / black","Terrain or obstacles well below the aircraft"],["Blue","Sea-level water"],["Magenta dots","Terrain elevation not known"]]},note:"Peaks Mode shows two numbers in the lower left of the terrain display: the highest terrain/obstacle in the selected range (colored red/yellow/green per its relationship to aircraft altitude), and the green/black interface altitude — both in feet AMSL."},{heading:"Look-Ahead mode",paragraphs:["Using the predicted flight path vector compared to the terrain/obstacle database, Look-Ahead issues a caution at roughly 30 seconds from impact and escalates to a warning at roughly 20 seconds — both remain active until the aircraft maneuvers clear. Alert timing is slightly reduced in low altitude mode.","Look-Ahead is inhibited when TER INHB is selected or airspeed is below 70 KIAS. If GPS is lost, EGPWS dead-reckons for 60 seconds; if GPS isn't regained, a 'BE ALERT, TERRAIN INOP' aural sounds and the terrain map is removed.","When an alert occurs, the terrain display range automatically changes to 5 NM (2.5 NM in low altitude mode) and the offending terrain area is enlarged on the display (cell expansion) to draw attention to it. If no terrain display is selected anywhere when an alert triggers, the system pops one up automatically — center MFD first, then pilot inboard, then copilot inboard MFD (disabled with two or fewer MFDs operational)."],table:{columns:["Alert","Aural / visual"],rows:[["Caution, ~30 s to impact","'Caution Terrain, Caution Terrain' (or Obstacle) every 7 s; yellow TERRAIN/OBSTACLE on ADI"],["Warning, ~20 s to impact","Continuous 'Warning Terrain' (or Obstacle); red TERRAIN/OBSTACLE on ADI"]]}},{heading:"Basic modes",table:{columns:["Mode","What it catches","Key detail"],rows:[["2 — Excessive Terrain Closure Rate","Closing with terrain too fast — descending, level, or even climbing over rising terrain.","Mode 2A is primary; Mode 2B desensitizes with gear down, on an ILS approach, or within 60 s of takeoff. Also inhibited when Look-Ahead is functioning with high integrity, in low altitude mode, or during autorotation. 'TERRAIN' caution escalates to continuous 'PULL UP' warning."],["3 — Inadvertent Descent After Takeoff","Significant altitude loss right after takeoff.","Active once gear is up or airspeed exceeds 50 KIAS; stays active until ~60 s after takeoff. Alert boundary is a function of height above terrain and elapsed time. Inhibited in low altitude mode. 'DON'T SINK' caution."],["4A — Unsafe Terrain Clearance, gear up","Insufficient clearance in cruise/approach with gear up.","'TOO LOW TERRAIN' above 60 KIAS below 150 ft radar altitude; 'TOO LOW GEAR' at or below 60 KIAS below 150 ft."],["4B — Unsafe Terrain Clearance, gear down","Insufficient clearance in cruise/approach with gear down.","'TOO LOW TERRAIN' above 120 KIAS below 100 ft, tightening to 10 ft by 80 KIAS. Mode 4 gear-warning floor raises to 400 ft AGL in autorotation; mode 4 altitude warnings (but not gear warnings) are inhibited in low altitude mode."],["4C — Unsafe Terrain Clearance, takeoff","Rapidly rising terrain during a climbing takeoff.","Floor is 75% of current radar altitude — can trigger even while climbing, if terrain is rising faster."],["5 — Glideslope Alert","Descending below ILS glideslope.","Soft alert (quieter) beyond 1.3 dots low; hard alert below 300 ft AGL and beyond 2 dots low. Requires ILS as active nav source, valid glideslope, radar altitude <1,000 ft, gear down. Inhibited by G/S CNCL, which rearms above 2,000 ft AGL, below 50 ft AGL, or on tuning a different ILS frequency."],["6 — Additional Alerts","Excessive bank, tail-strike risk, altitude callouts.","'BANK ANGLE' aural given twice then suppressed until bank increases another 20%. 'TAIL TOO LOW' based on radar altitude, pitch, pitch rate and descent rate, continuous while in the warning boundary. Configurable altitude callouts (default 100 ft) — factory-set, not aircrew-adjustable, re-arm after climbing 50 ft above the callout altitude."]]}},{heading:"Controls",table:{columns:["Control","Function"],rows:[["TER INHB","Inhibits the Look-Ahead modes"],["LOW ALT","Desensitizes the system for low-altitude VFR flight"],["AUD INHB","Silences most aural alerts (visual alerts stay active) for 5 minutes, or until pressed again"],["G/S CNCL","Cancels below-glideslope warnings for an ILS approach not being flown to minimums; rearms above 2,000 ft AGL, below 50 ft AGL, or on a new ILS frequency"]]},note:"Since EGPWS and weather radar share display colors, the two cannot be selected simultaneously on the same MFD. EGPWS ground test (engines off only) runs a full IBIT sequence across two MFDs and takes about 20 seconds, ending in a TEST PASSED message."}]},{slug:"afcs",title:"AFCS: The Coupled Flight Director",subtitle:"Dual-redundant SAS, Attitude Hold, and Coupled Flight Director — every basic mode's engagement logic, power limiting, and what happens automatically on an engine failure while coupled.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 16 (AFCS — Introduction, Operation, Sensors, Servo Actuators, Flight Control Computers, SAS, AP, Coupled Flight Director, Cockpit Controls, Pilot Interface, CFD Mode Engagement, Basic Modes, Navigation Modes, Approach Modes).",sections:[{heading:"The architecture",paragraphs:["The AFCS is dual-redundant in every feature except the trim actuators, built from sensors (rate gyros, dual AHRS, accelerometers, RVDTs, ADCs, radar altimeter, nav radios, FMS, FADEC), two Flight Control Computers (FCCs — each with an independent SAS section and AP section, separate sensors and power supplies), and servo actuators (trim, SAS, boost).","Three layers stack on top of each other. SAS provides basic rate damping — it senses a disturbance (a gust-induced nose pitch-up, say) and makes small, immediate corrections without trying to return the aircraft to its original attitude. AP adds attitude hold on top of SAS: it remembers the trimmed pitch/roll/yaw attitude and actively works to regain it after a disturbance, plus hover augmentation, gust alleviation, and heading hold (below 50 KIAS) or heading hold with turn coordination (above 50 KIAS). The Coupled Flight Director (CFD) sits on top of both, using the trim actuators to fly a pilot-selected path hands-off."]},{heading:"SAS servos vs. trim actuators — what actually moves the stick",paragraphs:["Two sets of four hydraulic SAS servos (eight total, two per axis) make control inputs without moving the cockpit controls — each servo has 5% control authority, combining to 10% total per axis. If a primary SAS computer or its sensors fail, the pilot can select secondary SAS, in which the AP computer (using AHRS data) takes over that side.","Four electromechanical trim actuators, by contrast, do move the cockpit controls when they move — they provide control referencing and an artificial control gradient, each with 100% control authority but limited to 10%/second rate. Once trimmed, any control movement without releasing trim builds an increasing force back toward the reference. Trim actuators are what the AP and CFD use for their control inputs."]},{heading:"Cockpit controls",table:{columns:["Control","Function"],rows:[["AP1 / AP2","AP computers on/off — at least one must be on for attitude hold, turn coordination, coupled flight, and trim beepers to function"],["ATT / SAS","ATT (normal) = attitude hold plus AP enhancements active. SAS = attitude hold unavailable, AP enhancements still active"],["SAS1 / SAS2","Hydraulic power to the respective SAS servos — at least one must be on"],["PRI / SEC (SAS)","PRI (normal) = primary SAS computer, driven by rate gyros. SEC = AP computer, driven by AHRS, controls the SAS servos instead"],["Yaw trim / Cyclic trim buttons","Turn the respective trim actuators on/off — required for pedal/cyclic position hold, turn coordination, heading hold, and attitude hold to function on that axis"],["Collective trim","Turns the collective trim actuator on/off — required for collective position hold and beep trim"],["FD SELECT 1/2","Selects which Flight Director controls the coupled functions — the inactive Mode Select Panel is forced to standby"],["COUPLE","Lit when at least one axis is coupled; pressing it decouples the aircraft (CFD command bars remain displayed)"]]},note:"Pressing and holding the cyclic trim release frees pitch/roll stick forces with minimal resistance; the collective trim release trigger does the same for the collective. On release, the new position (plus, depending on active mode, the new attitude/airspeed/altitude) becomes the new trim reference. If bank exceeds 30\xb0 in ATT mode, the AFCS automatically works to bring it back to 30\xb0 once the trim button is released."},{heading:"Basic modes",table:{columns:["Mode","Engagement","Key numbers"],rows:[["Heading Hold (HDG)","Press HDG on the active MSP — aircraft turns immediately to the heading bug","Max 22\xb0 bank angle commanded during the turn"],["Airspeed Hold (AS)","Press AS — captures airspeed at time of engagement","Adjustable 55–155 KIAS via the longitudinal cyclic beeper"],["Barometric Altitude Hold (ALT)","Press ALT — captures baro altitude at time of engagement","Beep-trim climbs/descends at up to 500 fpm"],["Radar Altitude Hold (RALT)","Press RALT — captures radar altitude at time of engagement","Climb up to 500 fpm via beep; descent rate scales down from 500 fpm above 500 ft AGL to a 200 fpm max at/below 200 ft AGL"],["Vertical Speed (VS)","Press VS — captures VS at time of engagement","Adjustable via beep trim"],["Altitude Preselect (ALTP)","Set target altitude on the DCP, then press ALTP","Auto-selects VS at 500 fpm toward the target, adjustable by beep, captures automatically on arrival"],["Go Around (GA)","Cyclic button or MSP soft key, above 50 KIAS only","750 fpm climb via collective, 80 KIAS via pitch, present heading held via roll. ALTP still works if armed"]]},note:"The CFD will not couple to pitch or roll below 50 KIAS — radar altitude hold is the exception and can engage at any airspeed. Two-cue vs three-cue: whether vertical speed/altitude is held via the pitch axis (two cue) or the collective axis (three cue) changes which beeper does what — check the PFD's P/R/C axis annunciations to know which is active."},{heading:"Power limiting",paragraphs:["When coupled to the collective axis, the CFD automatically limits power to maximum continuous torque/TGT/Ng. On a power limit, the CFD trades airspeed to hold the desired altitude or climb rate, working toward bucket airspeed (minimum power required speed — 80 KIAS at sea level, decreasing 1 kt per 1,000 ft). If the aircraft reaches bucket speed and still can't hold the target, it will instead descend (in ALT) or reduce climb rate (in VS), with a yellow CHECK POWER advisory and a single aural alert.","Power limiting automatically shifts from maximum-continuous to takeoff power levels when descending below 200 ft AGL, reverting once the aircraft climbs back above 300 ft AGL."]},{heading:"Engine failure while coupled",paragraphs:["The pilot should always take manual control and fly the appropriate emergency procedure — but the CFD's automatic behavior in the interim is worth knowing. Coupled to the collective (three-cue): the CFD automatically lowers collective to restore Nr to 105% and stay below maximum continuous power, resetting the airspeed reference to bucket speed. Coupled to altitude/VS on the pitch axis (two-cue): the aircraft tries to hold by reducing airspeed; if power still isn't sufficient and airspeed drops below 50 KIAS, it auto-decouples — take control before decelerating below bucket speed. Airspeed coupled to pitch with no vertical mode selected: the airspeed reference resets to bucket speed automatically. If both engines fail while coupled, the collective axis auto-decouples."]},{heading:"Approach modes",paragraphs:["The CFD flies VOR, FMS, ILS, Pseudo-ILS (P-ILS), and Localizer Back Course approaches, all selectable in two-cue or three-cue — three-cue is recommended for all approaches since two-cue has no deceleration feature. VOR, basic FMS, and localizer approaches have no automatic vertical/airspeed function; the pilot can layer in altitude preselect, VS, or airspeed hold manually.","On an ILS with GS and DCL armed, the CFD flies a pre-programmed deceleration to 80 KIAS by 200 ft AGL, continuing to 60 KIAS by 50 ft AGL, leveling at 50 ft AGL if GS is selected — the radar altimeter must be valid for DCL to function, and changing the airspeed reference while DCL is armed will de-arm it. P-ILS lets the CFD carry ILS-style glideslope, deceleration, and level-off features on an FMS-based approach, transitioning automatically from FMS flight plan to FMS approach to P-ILS as each phase is intercepted.","VOR station passage uses DME (switching at 1.5 DME, or 1.3 in VOR approach mode) or, without DME, needle-swing rate to detect the station and smooth the transition to the outbound course — the green NAV annunciation flashes throughout. A noisy or unreliable VOR signal can cause false 'S' turns or a false station-passage detection; monitor raw VOR data and deselect NAV if the course indicator moves erratically."]}]},{slug:"mgb-lubrication-warning-system",title:"MGB Lubrication and Warning System",subtitle:"The main gearbox's own layered defense — pressure alert, oil-hot caution, five chip detectors, and the bearing monitor system, with the exact caution/warning split.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 12 (Powertrain — Introduction, Components, MGB Lubrication System, MGB Indicating System, MGB Oil Pressure Alert System, MGB Oil Bypass Switch, MGB Oil Hot Caution, MGB Chip Detection, Bearing Monitor System, Rotor Brake).",sections:[{heading:"What it is",paragraphs:["The Main Gearbox (MGB) sits atop the cabin forward of the two engines, built from five modules — two input modules, two accessory modules, and the main module — with a built-in 5\xb0 forward tilt. Dual pumps mounted on the front of the MGB supply cooled, filtered oil to all bearings and gears; an external radiator cooled by a blower on the tail rotor drive shaft prevents overheating, with a bypass valve able to isolate the cooler entirely. The oil filter has an impending-bypass button that should be checked on preflight for contamination.","The oil temperature and pressure gauges live in the EICAS MGB group (PSI / \xb0C), fed independently through each DCU — the border, digital readout, and tape turn yellow if either value moves outside normal range, and red if it reaches a never-exceed value."]},{heading:"Oil pressure alert — a separate system from the gauge",paragraphs:["Independent of the cockpit pressure gauge, a dedicated alert system monitors oil pressure at the input manifold and at the 'last jet' of the left accessory module via two pressure switches that close when pressure drops below minimum. If either switch trips: MGB OIL PRES caution. If both trip together: MGB OIL PRES warning, with a 'GEARBOX PRESSURE' aural alert. This dual-switch design is the difference between a single-point sensor fault and a genuine dual-indication pressure loss."]},{heading:"Oil bypass switch",table:{columns:["Position","Function"],rows:[["NORM","Oil routed through the cooler — normal operation"],["TEST","Momentary — actuates the bypass valve to verify function, MGB BYPASS caution illuminates, returns to NORM on release"],["BYP","Pull and move to BYP — isolates the cooler and its external hoses from the MGB lubrication system, MGB BYPASS caution illuminates, stays in BYP until manually returned to NORM"]]}},{heading:"MGB OIL HOT",paragraphs:["Each chip detector doubles as a temperature sensor — high oil temperature triggers the MGB OIL HOT caution and, crucially, also disables the chip detector's fuzz burn-off feature, to prevent electrical arcing while the oil is in a vaporous state near that temperature. Power for this caution comes from the DC ESSENTIAL bus via the M XMSN OIL WARN breaker — the same circuit as the oil pressure alert system."]},{heading:"Chip detection",paragraphs:["Five chip detectors — one each in the MGB, both input modules, and both accessory modules — feed a chip detector processor, generating MGB CHIP, INPUT 1/2 CHIP, and ACC 1/2 CHIP cautions independently. A 30-second time-delay relay lets small chips and fuzz burn off or wash away before triggering a caution, preventing false alarms from normal wear debris — this fuzz burn-off function is what MGB OIL HOT disables. The detector runs a Built-In-Test on startup; a BIT failure shows CHIP SYS FAULT."]},{heading:"Bearing Monitor System (BMS)",paragraphs:["The BMS processes vibration and temperature data from the swashplate, tail rotor drive shaft bearings #1 and #2, and the oil cooler bearing. An out-of-limit reading on any of them illuminates CHECK BMS. Swashplate over-temperature specifically can escalate to a warning or caution depending on severity — a separate, more serious condition from the routine BMS advisory."]},{heading:"Rotor brake — a separate hydraulic circuit",paragraphs:["The rotor brake pad/disc assembly mounts on the MGB tail rotor output flange, engaged by pulling down and forward on a handle over the pilot's left shoulder — more forward movement or repeated strokes increases brake pressure, shown on an adjacent gauge. The rotor brake reservoir doubles as the servicing reservoir for hydraulic systems 1, 2, and 3.","Both engines can be started with the rotor brake set — the FADEC won't advance either engine past idle until Np exceeds 24%. The rotor brake is not designed to stop the rotor before shutdown; it's a hold/slow-down function, not a rapid-stop function. Pressure and puck-position sensors drive the ROTOR BRAKE caution: on the ground, either sensor alone triggers it; in the air, both sensors must agree to trigger it."]}]},{slug:"hydraulic-system",title:"Hydraulic System",subtitle:"Three fully independent systems with full cross-redundancy, plus Leak Detection and Isolation — how a single leak gets contained without taking down a second system.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 14 (Hydraulic System — Introduction, Hydraulic System Controls, Hydraulic Pressure Indicator, Hydraulic Pump Modules, Heat Exchangers, Transfer Modules, Automatic Backup Shutoff Valve Operation, Leak Detection and Isolation, Main Rotor Servos, Tail Rotor Servos, Operation).",sections:[{heading:"Three independent systems, full redundancy",paragraphs:["No. 1 and No. 2 are the primary flight-control hydraulic systems, each fully capable on its own. No. 3 is a genuine backup — it can supply either or both of No. 1/No. 2 if a pump fails, and independently powers the landing gear, cargo ramp, and automatic APU accumulator recharge. All three are completely independent constant-pressure systems (4,000 psi, up to 13 GPM each on No. 1/2); No. 1 and No. 2 pump modules are identical and interchangeable, driven by their respective accessory modules. No. 3 is driven directly off the main gearbox, with a separate reservoir and an AC-motor-driven ground-checkout mode for pre-rotor testing.","A four-channel boost system (collective, pitch, roll, yaw) is powered by No. 2 hydraulics via a BST switch — turning it OFF illuminates BOOST PRES and noticeably increases control forces (cyclic roughly 1 lb → 6 lb per axis; collective/yaw roughly 4 lb → 13 lb), with some collective-to-yaw interaction. SAS hydraulic power comes through shutoff valves on the pilot-assist manifold, controlled by the SAS1/SAS2 switches on the AFCS panel — below 1,100 psi, SAS 1 PRES or SAS 2 PRES illuminates."]},{heading:"The SERVO switch — isolating one side deliberately",paragraphs:["A SERVO switch (NO. 1 / BOTH / NO. 2) on the upper console turns off one side of the three primary flight-control servos and the tail rotor servo. Selecting NO. 1 turns off the No. 2 servo side (MR SVO 2 PRES and TR SVO 2 PRES illuminate); selecting NO. 2 turns off the No. 1 side (MR SVO 1 PRES and TR SVO 1 PRES illuminate). An interlock prevents deliberately turning off a servo side while the other side has already lost pressure — and if the side left running loses pressure, the previously-off side automatically re-enables."]},{heading:"Automatic backup shutoff valves",paragraphs:["Both backup shutoff valves (which connect No. 3 to No. 1/No. 2) close automatically during engine start and shutdown, to prevent unwanted pressure shuttling between systems. During start, the DCUs close them once the first engine passes 15% Ng, reopening once Nr exceeds 50%. During shutdown, they close once Nr drops below 50%, reopening two minutes after the last engine's Ng drops below 15%.","With the backup shutoff valves closed, No. 3 pressure is unavailable to the primary, SAS, and boost servos — but remains available for the ramp, landing gear, and APU accumulator. During engine start, the pilot cannot move the flight controls until No. 1 and/or No. 2 pressure is established, regardless of No. 3 status; after shutdown, No. 3 can't be used to move the flight controls until the two-minute reopen delay has elapsed."]},{heading:"Leak Detection and Isolation (LDI)",paragraphs:["If a No. 1 or No. 2 reservoir level drops below its set limit: the corresponding RSVR LOW caution illuminates, that system's tail rotor shutoff valve closes to isolate a possible leak in the tail rotor circuit, and its backup shutoff valve closes to isolate the leaking primary system from No. 3 — protecting the No. 3 backup capability for the still-healthy system. A subsequent leak in the other primary system does not also trigger those valves; each side is isolated independently as its own leak is detected."]},{heading:"Failure indications",table:{columns:["Indication","Trigger"],rows:[["HYD 1/2/3 RSVR LOW","Fluid level below normal in that system's reservoir"],["HYD 1/2 PUMP FAIL","Pressure below 1,900–2,050 psi"],["HYD 3 PUMP FAIL","Below 500 psi in depress mode, or below 2,000 psi in high mode"],["HYDR 1/2/3 TEMP ALERT","Fluid temperature above 110\xb0C"],["HYDR 1/2/3 TEMP LIMIT","Fluid temperature above 135\xb0C"],["HYDR FAN FAIL","Both cooling fans (of that heat exchanger pair) have failed"]]},note:"The No. 3 system runs at a lower pressure range in depress mode when idle, switching to the full 3,500–4,200 psi high mode (HYD 3 HI MODE advisory) whenever it's actually being used — landing gear, ramp, or backing up No. 1/2."}]},{slug:"engine-blowaway-oei-power",title:"Engine: Blowaway Logic and OEI Power",subtitle:"How the FADEC automatically raises power limits when Nr droops, the three OEI power ranges, and exactly how each one gets armed.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 8 (Engine — Introduction, Engine Governing, Blowaway, Single Engine Operations, Engine Control Quadrant).",sections:[{heading:"What it is",paragraphs:["Two CT7-8/CT7-8A turboshaft engines, each controlled by a dual-channel FADEC (channels A and B swap control after every shutdown; a degraded channel hands control to the healthier one). During normal all-engines-operative flight, the FADEC holds Nr at a constant 105% with matched torque between engines — though if a high-margin engine is paired with a low-margin one, the FADEC will command up to a 10% torque split at the upper power ranges to compensate.","Engine and gearbox protection limits are built into the FADEC to keep the pilot within posted limits automatically — separate limits exist for AEO and OEI. Blowaway is the logic that shifts those limits upward temporarily when the situation genuinely demands more power than the normal limit allows."]},{heading:"How blowaway triggers",paragraphs:["When the AEO takeoff limit is reached (100% torque or 995\xb0C TGT), the FADEC limits fuel flow, causing Nr to droop. If that droop takes Nr below 100%, blowaway activates: if both engines are on a TGT limit, the FADEC automatically shifts them into the 30-second power TGT rating (no TGT blowaway exists for OEI). If the aircraft is limited by MGB torque instead, the FADEC increases the torque limit per the blowaway schedule — separate schedules exist for dual-engine and single-engine conditions, and for normal vs. training modes."]},{heading:"Detecting an engine failure",paragraphs:["The FADEC declares an engine failure two ways: if Ng decreases faster than the FADEC itself is commanding, or if Ng drops below 55%. On detection: an 'ENGINE 1' or 'ENGINE 2 FAILURE' aural, a red ENGINE FAIL warning light, and a red X over the affected engine's pod symbol."]},{heading:"Three OEI power ranges",table:{columns:["Range","Purpose"],rows:[["30 second","Stops the initial descent after an engine failure, helps recover Nr and airspeed to normal range"],["Two minute","Climbs the aircraft away from threatening terrain"],["Maximum continuous","Cruise to a safe landing zone"]]},note:"After a failure, the PFD TGT gauge shows the armed limiter (30 SEC or 2 MIN, white, upper right) and the range actually in use (yellow, upper left), with a countdown arc that turns red at zero."},{heading:"How each OEI range gets armed",paragraphs:["The FADEC arms limits automatically in three cases: when one engine fails, the remaining engine auto-arms 30-second power; when one throttle is pulled out of FLY, the good engine auto-arms two-minute power; and if torque split exceeds 20% with the low engine below 70% torque, the good engine auto-arms two-minute power.","The pilot can also select manually via the OEI SEL switch: push forward for 30-second power, pull back for two-minute power, plunge down for maximum continuous. There is no direct path from 30-second to maximum continuous — the pilot must pass through two-minute first — but maximum continuous can go directly back to 30-second. Any attempt to exceed the currently selected power limit will droop the rotor rather than deliver more power."]},{heading:"Throttle positions",table:{columns:["Position","Effect"],rows:[["STOP","FADEC shuts the engine down"],["IDLE","FADEC commands idle Ng of approximately 67%"],["FLY","Normal governed operation"]]},note:"There is no mechanical linkage between the throttles and the FADEC or engines — throttle position is sent electronically via RVDT position sensors and quadrant microswitches."}]},{slug:"emergency-flotation-system",title:"Emergency Flotation System",subtitle:"Weight-dependent sea-state design margins, three independently-pocketed float bags, and the self-test warning about a faulty immersion switch.",rfmReference:"S-92A RFM Part 2, Section I, Chapter 18 (Options — Emergency Flotation System: Introduction, Flotation Control, Flotation System Test Procedure).",sections:[{heading:"What it's designed to do",paragraphs:["At aircraft weights at or above 18,590 lb (8,432 kg), the system is designed to keep the helicopter upright and afloat long enough for full evacuation in mid Sea State 5 (8–12 ft waves, 18–25 kt wind). Below that weight, the design margin is mid Sea State 4 (4–8 ft waves, 17–21 kt wind) — a real, weight-dependent difference in the survivability margin, not just a certification footnote.","Two forward float bags mount below the cockpit jettisonable windows; one aft bag mounts externally on the underside of the tail. Each of the three bags has two separate, independent pockets — if one pocket fails, the other still provides buoyancy for that section of the aircraft. Four nitrogen bottles inflate the system: two under-floor bottles near the forward entrance (one pocket each of the left/right forward floats), and two in the tail boom (one pocket each of the aft float)."]},{heading:"Activation",paragraphs:["When armed, the system inflates automatically on water contact (via immersion switches) or can be triggered manually by the crew. Control comes from three places: the primary FLOTATION panel (SAFE/ARM/TEST toggle, plus a TEST rotary switch with NORM/PRI/SEC/L IMRS/R IMRS positions), the AUX FLOTATION panel (a separate SAFE/ARM toggle on the left side of the cockpit), and guarded EMER FLOATS switches on each collective grip — pressing either collective switch with the system armed fires both the primary and secondary flotation relays.","Power comes from the No. 1 DC PRI bus (FLOAT PWR breaker) and the battery bus (FLOAT PWR breaker) — a genuinely dual-sourced supply, so a single bus loss doesn't take the system down."]},{heading:"The self-test warning",paragraphs:["The test sequence cycles the TEST rotary switch through PRI, SEC, L IMRS, and R IMRS, confirming ARMED stays dark and TEST stays lit at each position, with L/R indications appearing only when expected. The RFM is explicit about the risk: continue only if the green TEST light is illuminated — if any L/R indicator illuminates unexpectedly during the test, it may point to a faulty immersion switch, and with the system in ARMED, a faulty immersion switch can cause immediate, unintended float deployment."]}]}];function n(){return(0,i.jsx)(o.A,{title:"S-92 SYSTEM NOTES",basePath:"/s92/system-notes",data:r})}},98172:(e,t,a)=>{Promise.resolve().then(a.bind(a,89473))}},e=>{e.O(0,[2619,8441,1255,7358],()=>e(e.s=98172)),_N_E=e.O()}]);